INSERT INTO tickets (category, severity, title, description, root_cause, resolution, file_path, resolved_at, resolution_time_minutes) VALUES
('bug', 'medium', 'Login endpoint returns 500 on empty password', 'When a user submits the login form with an empty password field, the /auth/login endpoint crashes with a 500 error instead of returning a validation message. Stack trace points to a NoneType comparison in the password check.', 'The password verification function called check_password_hash() without first validating that the submitted password was non-empty, causing a NoneType error.', 'Added an explicit empty-field check before the hash comparison and returned a 400 validation response for empty credentials.', 'flask/auth/views.py', NOW() - INTERVAL '85 days', 95),
('bug', 'medium', 'Off-by-one error in pagination page count', 'The pagination on the /items listing page shows one fewer page than expected. When there are exactly 20 items with a page size of 10, only one page link appears instead of two.', 'The total page count calculation used integer division without accounting for the remainder, producing an off-by-one error.', 'Replaced floor division with a ceiling calculation using (total + per_page - 1) // per_page.', 'flask/pagination.py', NOW() - INTERVAL '136 days', 60),
('bug', 'high', 'JSON response missing Content-Type header', 'API responses from /api/data return valid JSON but omit the Content-Type: application/json header, causing some clients to misparse the body as plain text.', 'The custom response builder set the body but never set the mimetype, defaulting to text/html.', 'Set mimetype=''application/json'' explicitly in the response constructor.', 'flask/helpers.py', NOW() - INTERVAL '271 days', 45),
('bug', 'high', 'Session cookie not cleared on logout', 'After a user clicks logout, the session cookie persists and the user remains authenticated on refresh. Expected behaviour is full session termination.', 'The logout handler cleared the server-side session dict but did not delete the client session cookie.', 'Called session.clear() and set the cookie to expire immediately in the logout response.', 'flask/auth/views.py', NOW() - INTERVAL '311 days', 75),
('bug', 'high', 'Unicode filenames cause upload failure', 'Uploading a file with non-ASCII characters in the filename (e.g. accented characters) raises a UnicodeEncodeError and the upload fails.', 'The file-save routine encoded the filename using ASCII instead of UTF-8.', 'Switched filename handling to use secure_filename with UTF-8 encoding.', 'flask/uploads.py', NOW() - INTERVAL '217 days', 90),
('bug', 'high', 'Division by zero in average rating calculation', 'The product page crashes with a ZeroDivisionError when a product has no ratings yet, because the average is computed by dividing the rating sum by the rating count.', 'The average calculation did not guard against a zero rating count for new products.', 'Added a guard returning 0.0 when the rating count is zero before performing the division.', 'flask/models/product.py', NOW() - INTERVAL '109 days', 40),
('bug', 'medium', 'Incorrect date formatting in exported CSV', 'Dates in the exported CSV appear in US format (MM/DD/YYYY) instead of the expected ISO format (YYYY-MM-DD), breaking downstream imports.', 'The CSV writer used the default locale date format rather than an explicit ISO format string.', 'Applied strftime(''%Y-%m-%d'') explicitly when writing date columns.', 'flask/export.py', NOW() - INTERVAL '277 days', 55),
('bug', 'medium', 'Race condition in counter increment', 'Under concurrent requests, the view counter occasionally skips increments, producing counts lower than the actual number of requests.', 'The counter read-modify-write sequence was not atomic, causing lost updates under concurrency.', 'Replaced the manual increment with an atomic SQL UPDATE ... SET count = count + 1.', 'flask/models/stats.py', NOW() - INTERVAL '354 days', 120),
('bug', 'critical', 'Memory leak in image thumbnail cache', 'The thumbnail cache grows without bound, eventually exhausting memory on long-running instances, because generated thumbnails are never evicted.', 'The cache dictionary had no size limit or eviction policy.', 'Replaced the plain dict with an LRU cache capped at 500 entries.', 'flask/cache.py', NOW() - INTERVAL '103 days', 150),
('bug', 'medium', 'Broken redirect after form submission', 'After submitting the contact form, users are redirected to a 404 page instead of the confirmation page due to an incorrect url_for target.', 'The redirect referenced a renamed endpoint that no longer existed.', 'Updated the url_for call to reference the correct ''contact_confirm'' endpoint name.', 'flask/views/contact.py', NOW() - INTERVAL '160 days', 35),
('bug', 'low', 'Null pointer when profile has no avatar', 'A defect was reported: null pointer when profile has no avatar. Users experience incorrect behaviour that deviates from the documented specification, and the issue is reproducible in the affected module.', 'Root cause traced to faulty logic in flask/models/user.py where an edge case was not handled correctly.', 'Corrected the logic in flask/models/user.py, added a guard for the edge case, and covered it with a regression test.', 'flask/models/user.py', NOW() - INTERVAL '205 days', 53),
('bug', 'medium', 'Timezone offset ignored in scheduler', 'A defect was reported: timezone offset ignored in scheduler. Users experience incorrect behaviour that deviates from the documented specification, and the issue is reproducible in the affected module.', 'Root cause traced to faulty logic in flask/scheduler.py where an edge case was not handled correctly.', 'Corrected the logic in flask/scheduler.py, added a guard for the edge case, and covered it with a regression test.', 'flask/scheduler.py', NOW() - INTERVAL '344 days', 89),
('bug', 'low', 'Incorrect HTTP status on validation error', 'A defect was reported: incorrect http status on validation error. Users experience incorrect behaviour that deviates from the documented specification, and the issue is reproducible in the affected module.', 'Root cause traced to faulty logic in flask/views/api.py where an edge case was not handled correctly.', 'Corrected the logic in flask/views/api.py, added a guard for the edge case, and covered it with a regression test.', 'flask/views/api.py', NOW() - INTERVAL '333 days', 173),
